using System;
using System.Text;
using System.Web;
namespace TCPipeAutoDraw.UI.Studio
{
    internal static class CDBoxStudioSettingsPage
    {
        public static string BuildStandaloneDocument()
        {
            var settings=CDBoxStudioSettingsStore.Load();
            var plan=CDBoxStudioComponentUpdatePlan.Capture();
            string version=CDBoxStudioUpdateService.CurrentVersion;
            return BuildDocument(settings, plan.Summary, plan.Warning, version);
        }
        internal static string BuildDocument(CDBoxStudioSettings settings, string summary, string warning, string version)
        {
            settings.Normalize();
            string body=Body.Replace("@@COMPONENTS@@",HttpUtility.HtmlEncode(summary))
                .Replace("@@WARNING@@",HttpUtility.HtmlEncode(warning)).Replace("@@VERSION@@",HttpUtility.HtmlEncode(version))
                .Replace("@@RELEASE@@",CDBoxReleaseUpdatePage.BuildControls(settings));
            return CDBoxAccentAppearance.Attach("<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>CDBox 设置</title><style>"
                + Styles + CDBoxWorkbenchAppearance.BuildThemeStyles(settings) + "</style></head><body data-appearance='workbench' data-theme=\""
                + CDBoxWorkbenchAppearance.ResolveTheme(settings.Theme) + "\">" + body
                + "<script>window.CDBoxSettingsContext=" + CDBoxThemeCatalog.Json(new {settings, presets=CDBoxThemeCatalog.Presets, version}) + ";"
                + CDBoxWorkbenchThemeScript.Build() + CDBoxReleaseUpdatePage.BuildScript() + Script + "</script></body></html>", settings);
        }
        private static readonly string Body = @"<main class=""settings-shell""><aside class=""settings-nav""><div class=""nav-title"">CDBox 设置</div><nav aria-label=""设置分类""><button data-section=""appearance"" aria-current=""page"">外观</button><button data-section=""floating"">悬浮球与浮窗</button><button data-section=""drawing"">绘图与交互</button><button data-section=""updates"">安装与更新</button></nav><div class=""nav-foot"">CDBox <span id=""appVersion""></span></div></aside><section class=""settings-main""><header class=""settings-top""><h1 id=""sectionTitle"">外观</h1><span id=""saveStatus"" role=""status"">设置已加载</span><button id=""retrySettings"" hidden>重试</button></header><div class=""settings-content"">
<section data-panel=""appearance""><div class=""intro""><h2>外观与主题</h2><p>为浅色和深色分别选择主题，修改即预览并保存。</p></div>
<div class=""setting-row""><span>外观模式</span><div class=""segmented"" role=""group"" aria-label=""外观模式""><button data-mode=""light"">浅色</button><button data-mode=""dark"">深色</button></div></div>
<div class=""theme-editor""><div class=""setting-row theme-heading""><h3 id=""themeTitle"">浅色主题</h3><div class=""row-controls""><button class=""quiet"" id=""importTheme"">导入</button><button class=""quiet"" id=""copyTheme"">复制主题</button><span class=""type-mark"" aria-hidden=""true"">Aa</span><select id=""themePreset"" aria-label=""主题预设""></select></div></div>
<div class=""setting-row""><label for=""Accent"">强调色</label><div class=""row-controls""><select id=""AccentSource"" aria-label=""强调色来源""><option value=""custom"">自定义</option><option value=""foreground"">跟随前景</option></select><div class=""color-control""><input id=""AccentPicker"" type=""color"" aria-label=""选择强调色""><input id=""Accent"" maxlength=""7"" aria-label=""强调色 HEX"" spellcheck=""false""></div></div></div>
<div class=""setting-row""><label for=""Background"">背景</label><div class=""color-control""><input id=""BackgroundPicker"" type=""color"" aria-label=""选择背景色""><input id=""Background"" maxlength=""7"" aria-label=""背景 HEX"" spellcheck=""false""></div></div>
<div class=""setting-row""><label for=""Foreground"">前景</label><div class=""color-control""><input id=""ForegroundPicker"" type=""color"" aria-label=""选择前景色""><input id=""Foreground"" maxlength=""7"" aria-label=""前景 HEX"" spellcheck=""false""></div></div>
<div class=""setting-row""><label for=""UiFont"">UI 字体</label><div class=""row-controls""><select id=""UiFont"" aria-label=""UI 字体""></select><select id=""UiWeight"" aria-label=""UI 字重""></select></div></div>
<div class=""setting-row""><label for=""ContentFont"">内容字体</label><div class=""row-controls""><select id=""ContentFont"" aria-label=""内容字体""></select><select id=""ContentWeight"" aria-label=""内容字重""></select></div></div>
<div class=""setting-row""><label for=""Contrast"">对比度</label><div class=""row-controls""><input id=""Contrast"" type=""range"" min=""0"" max=""100"" step=""1""><output id=""contrastValue"" for=""Contrast"">50</output></div></div></div>
<p class=""hint"" id=""themeHint"" role=""status"">对比度调整分隔线与控件边界的清晰程度。</p>
<div class=""setting-row""><div><label for=""animations"">界面动画</label><p>平滑切换导航、展开和折叠内容</p></div><input id=""animations"" type=""checkbox"" class=""toggle""></div>
</section>
<section data-panel=""floating"" hidden><div class=""intro""><h2>悬浮球与浮窗</h2><p>保持常用操作随手可及，减少对绘图区域的遮挡。</p></div><h3 class=""section-label"">悬浮球</h3><div id=""floatingRows""></div><h3 class=""section-label"">标注与提示浮窗</h3><div id=""hudRows""></div></section>
<section data-panel=""drawing"" hidden><div class=""intro""><h2>绘图与交互</h2><p>控制 CAD 对象的颜色写入和快捷操作。</p></div><div class=""setting-row""><div><label for=""colorOutputMode"">CAD 颜色写入方式</label><p>默认保留对象原有的 ACI／真彩色类型</p></div><select id=""colorOutputMode""><option value=""PreserveOriginalType"">保持原类型</option><option value=""PreferIndexColor"">优先索引颜色</option><option value=""PreferTrueColor"">优先真彩色</option><option value=""CDBoxStandard"">CDBox 标准颜色</option></select></div><div class=""setting-row""><div><label for=""doubleClickOpen"">双击快捷打开</label><p>双击标注浮窗和属性编辑器对应对象时打开编辑</p></div><input id=""doubleClickOpen"" type=""checkbox"" class=""toggle""></div></section>
<section data-panel=""updates"" hidden><div class=""intro""><h2>安装与更新</h2><p>查看组件、管理安装并检查新版本。</p></div><div class=""setting-row""><span>当前版本</span><strong>@@VERSION@@</strong></div><div class=""setting-row""><span>已安装组件</span><span class=""component-summary"">@@COMPONENTS@@</span></div><p class=""hint"">@@WARNING@@</p><div class=""actions""><button data-route=""openInstaller"">打开组件管理器</button><button data-route=""openLogs"">打开日志目录</button></div><p class=""hint"">组件管理器支持增加、移除业务模块和完整卸载。</p><div class=""release-block"">@@RELEASE@@</div></section>
</div></section></main>
<dialog id=""themeImportDialog""><form method=""dialog""><div class=""dialog-head""><h2>导入主题</h2><button value=""cancel"" aria-label=""关闭主题导入"">×</button></div><p>粘贴通过“复制主题”得到的 CDBox 主题 JSON，将应用到当前模式。</p><textarea id=""themeImportText"" rows=""8"" aria-label=""主题 JSON"" spellcheck=""false""></textarea><p id=""importError"" role=""alert""></p><div class=""actions""><button value=""cancel"">取消</button><button id=""applyImport"" type=""button"" class=""primary"">应用主题</button></div></form></dialog>";
        private static readonly string Styles = @"*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden}body{background:var(--bg);color:var(--text);font:13px/1.5 var(--ui-font)}button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button,select,input[type=number],input[type=url]{height:32px;padding:0 10px;background:var(--panel);border:1px solid var(--line-strong);border-radius:6px}button:hover{background:var(--hover)}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--focus);outline-offset:2px}button.primary{background:var(--brand);color:var(--on-brand);border-color:var(--brand)}[hidden]{display:none!important}.settings-shell{height:100%;display:grid;grid-template-columns:190px minmax(0,1fr)}.settings-nav{display:flex;flex-direction:column;min-height:0;padding:18px 10px 16px;border-right:1px solid var(--line);background:var(--sidebar)}.nav-title{padding:0 12px 24px;font-size:14px;font-weight:600}.settings-nav nav{display:grid;gap:5px}.settings-nav button{height:38px;text-align:left;padding:0 12px;border:0;background:transparent;color:var(--muted)}.settings-nav button[aria-current=page]{background:var(--selected);color:var(--text)}.settings-nav button:hover{background:var(--hover)}.nav-foot{margin-top:auto;padding:16px 12px 0;color:var(--muted);font-size:11px}.settings-main{min-width:0;display:flex;flex-direction:column;min-height:0}.settings-top{height:58px;flex-shrink:0;display:flex;align-items:center;gap:10px;padding:0 30px;border-bottom:1px solid var(--line)}.settings-top h1{font-size:14px;font-weight:500;margin:0}.settings-top #saveStatus{margin-left:auto;font-size:11px;color:var(--muted)}.settings-content{overflow:auto;scrollbar-gutter:stable;min-height:0;padding:16px 32px 40px}.settings-content>section{max-width:950px;margin:auto}.intro{margin:12px 0 26px}.intro h2{font-size:21px;font-weight:600;letter-spacing:-.4px;margin:0 0 7px}.intro p,.hint{color:var(--muted);font-size:12px}.intro p{margin:0}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:53px;padding:10px 0;border-bottom:1px solid var(--line)}.setting-row>label,.setting-row>div>label{font-weight:500}.setting-row p{font-size:12px;color:var(--muted);margin:3px 0 0}.row-controls{display:flex;gap:8px;align-items:center;flex:0 0 auto}.setting-row select{max-width:230px;font-size:12px}.theme-editor{margin-top:24px;background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:0 16px}.theme-editor .setting-row:last-child{border-bottom:0}.theme-heading h3{font-size:13px;margin:0;font-weight:600}.quiet{border:0;background:transparent;color:var(--muted);padding:0 4px;font-size:12px}.type-mark{font-size:12px;color:var(--focus);border:1px solid var(--line);border-radius:5px;padding:4px 6px}.theme-heading select{width:166px}.color-control{display:flex;align-items:center;width:166px;height:30px;border:1px solid var(--line);border-radius:8px;background:var(--bg);padding:0 8px;gap:7px}.color-control input[type=color]{width:16px;height:16px;flex:0 0 16px;border:0;padding:0;border-radius:50%;background:none;cursor:pointer}.color-control input[type=color]::-webkit-color-swatch-wrapper{padding:0}.color-control input[type=color]::-webkit-color-swatch{border:1px solid var(--line-strong);border-radius:50%}.color-control input:not([type=color]){min-width:0;width:110px;background:transparent;color:inherit;border:0;outline:none;font:12px Consolas,monospace}.color-control:focus-within{outline:2px solid var(--focus)}.color-control input[aria-invalid=true]{color:var(--danger)}input[type=range]{appearance:none;width:180px;height:2px;padding:0;border:0;background:var(--focus);accent-color:var(--focus)}input[type=range]::-webkit-slider-thumb{appearance:none;width:18px;height:18px;border-radius:50%;border:1px solid var(--line-strong);background:var(--text);cursor:pointer}output{min-width:30px;text-align:right;font-variant-numeric:tabular-nums}.segmented{display:flex;background:var(--panel2);padding:3px;border:1px solid var(--line);border-radius:8px;gap:3px}.segmented button{border:0;height:28px;min-width:60px;background:transparent;color:var(--muted)}.segmented button[aria-pressed=true]{background:var(--selected);color:var(--text)}.toggle{appearance:none;position:relative;width:32px;height:19px;border:1px solid var(--line-strong);border-radius:20px;background:var(--selected);cursor:pointer;flex:0 0 auto;transition:background .18s}.toggle:before{content:'';position:absolute;width:13px;height:13px;top:2px;left:2px;border-radius:50%;background:var(--muted);transition:transform .18s}.toggle:checked{background:var(--focus);border-color:var(--focus)}.toggle:checked:before{transform:translateX(13px);background:#fff}.section-label{font-size:12px;color:var(--muted);font-weight:500;margin:28px 0 0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.actions button{font-size:12px}.hint{line-height:1.7;margin:10px 0 16px}.release-block{border-top:1px solid var(--line);padding-top:16px;margin-top:26px}.release-block h3{font-size:14px;font-weight:500}.release-block p{color:var(--muted);font-size:12px}.release-fields input{height:34px;padding:0 10px;background:var(--panel);border:1px solid var(--line-strong);border-radius:6px;color:var(--text)}.release-fields label{font-size:12px;color:var(--muted)}.result{padding:14px 0;line-height:1.8;font-size:12px;overflow-wrap:anywhere}.component-summary{text-align:right;max-width:65%;color:var(--muted)}dialog{padding:22px;border:1px solid var(--line-strong);border-radius:10px;width:min(620px,90vw);background:var(--panel);color:var(--text);box-shadow:var(--popup-shadow)}dialog::backdrop{background:var(--overlay)}.dialog-head{display:flex;justify-content:space-between;align-items:center}.dialog-head h2{margin:0;font-size:16px}dialog p{font-size:12px;color:var(--muted)}dialog textarea{width:100%;resize:vertical;background:var(--bg);border:1px solid var(--line-strong);border-radius:5px;padding:10px;font:12px Consolas,monospace}#importError{color:var(--danger)}.toast{position:fixed;right:20px;bottom:20px;max-width:420px;padding:12px 16px;border:1px solid var(--line-strong);border-radius:7px;background:var(--panel);box-shadow:var(--popup-shadow)}.no-animations *{transition:none!important;animation:none!important}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}@media(max-width:980px){.settings-shell{grid-template-columns:160px minmax(0,1fr)}.settings-content{padding-inline:22px}.settings-top{padding-inline:22px}.row-controls{gap:6px}.setting-row{gap:12px}.theme-heading select{width:135px}.quiet{font-size:11px}}";
        private static readonly string Script = @"(function(){
const state=window.CDBoxSettingsContext,settings=state.settings,presets=state.presets,$=id=>document.getElementById(id);let saving=false,queued=false,lastSaved='',flight='',timer=0;
const clone=x=>JSON.parse(JSON.stringify(x));settings.Theme=settings.Theme==='dark'?'dark':'light';
const mode=()=>settings.Theme,p=()=>mode()==='dark'?settings.DarkTheme:settings.LightTheme;
function post(name,arg){if(window.chrome&&chrome.webview)chrome.webview.postMessage('studio|'+name+'|'+encodeURIComponent(arg||''));}
const toggles={animations:'AnimationsEnabled',floatingCenterEnabled:'FloatingCenterEnabled',floatingCenterShowOnStartup:'FloatingCenterShowOnStartup',floatingCenterSnapToEdges:'FloatingCenterSnapToEdges',floatingCenterAutoCheckEnabled:'FloatingCenterAutoCheckEnabled',floatingCenterSafeAutoSyncEnabled:'FloatingCenterSafeAutoSyncEnabled',hudGlowEnabled:'AnnotationHudGlowEnabled',doubleClickOpen:'DoubleClickOpenEnabled'};
function toggle(id,label,description){return `<div class=""setting-row""><div><label for=""${id}"">${label}</label>${description?`<p>${description}</p>`:''}</div><input id=""${id}"" type=""checkbox"" class=""toggle""></div>`;}
$('floatingRows').innerHTML=toggle('floatingCenterEnabled','启用悬浮球')+toggle('floatingCenterShowOnStartup','启动时显示','加载插件后显示悬浮球')+toggle('floatingCenterSnapToEdges','吸附屏幕边缘')+`<div class=""setting-row""><label for=""floatingCenterAutoCloseSeconds"">普通提示自动关闭</label><div class=""row-controls""><input id=""floatingCenterAutoCloseSeconds"" type=""number"" min=""1"" max=""30"" step=""1"" style=""width:74px""><span>秒</span></div></div>`+toggle('floatingCenterAutoCheckEnabled','自动检查图纸')+toggle('floatingCenterSafeAutoSyncEnabled','安全自动同步','允许安全的小范围同步');
function range(id,label){return `<div class=""setting-row""><label for=""${id}"">${label}</label><div class=""row-controls""><input type=""range"" id=""${id}"" min=""0"" max=""100"" step=""1""><output id=""${id}Value"">0%</output></div></div>`;}
$('hudRows').innerHTML=range('hudNormalOpacity','常态透明度')+range('hudHoverOpacity','鼠标悬停透明度')+toggle('hudGlowEnabled','边缘光圈')+range('hudGlowIntensity','光圈强度');
Object.entries(toggles).forEach(([id,key])=>$(id).checked=settings[key]);
const ranges={hudNormalOpacity:'AnnotationHudNormalOpacity',hudHoverOpacity:'AnnotationHudHoverOpacity',hudGlowIntensity:'AnnotationHudGlowIntensity'};
Object.entries(ranges).forEach(([id,key])=>{$(id).value=Math.round((id==='hudGlowIntensity'?settings[key]:(settings[key]-.2)/.8)*100);$(id+'Value').textContent=$(id).value+'%';$(id).oninput=()=>$(id+'Value').textContent=$(id).value+'%';});
$('floatingCenterAutoCloseSeconds').value=settings.FloatingCenterAutoCloseSeconds;$('colorOutputMode').value=settings.ColorOutputMode;$('appVersion').textContent=state.version;
const fonts={system:'系统默认',inherit:'与界面字体相同',segoe:'Segoe UI',yahei:'微软雅黑',sans:'Arial',serif:'Georgia / 宋体',mono:'Consolas 等宽'};
for(const id of ['UiFont','ContentFont'])$(id).innerHTML=Object.entries(fonts).filter(([key])=>id==='ContentFont'||key!=='inherit').map(([key,name])=>`<option value=""${key}"">${name}</option>`).join('');
for(const id of ['UiWeight','ContentWeight'])$(id).innerHTML='<option value=""400"">常规</option><option value=""500"">中等</option><option value=""600"">半粗</option>';
$('themePreset').innerHTML=presets.map(x=>`<option value=""${x.Id}"">${x.Name}</option>`).join('')+'<option value=""custom"">自定义</option>';
function apply(){window.CDBoxApplyWorkbenchTheme(settings);for(const key of ['Accent','Background','Foreground']){const color=p()[key],rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)),light=rgb[0]*.299+rgb[1]*.587+rgb[2]*.114>150;const control=$(key).parentElement;control.style.background=color;control.style.color=light?'#1A1C1F':'#FFFFFF';}document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode())));}
function draw(){const profile=p();$('themeTitle').textContent=(mode()==='dark'?'深色':'浅色')+'主题';$('themePreset').value=profile.Preset;for(const key of ['Accent','Background','Foreground','AccentSource','UiFont','ContentFont','UiWeight','ContentWeight','Contrast'])$(key).value=profile[key];for(const key of ['Accent','Background','Foreground']){$(key+'Picker').value=profile[key];$(key).removeAttribute('aria-invalid');}$('contrastValue').textContent=profile.Contrast;apply();}
function payload(){Object.entries(toggles).forEach(([id,key])=>settings[key]=$(id).checked);Object.entries(ranges).forEach(([id,key])=>settings[key]=id==='hudGlowIntensity'?Number($(id).value)/100:.2+Number($(id).value)*.008);settings.ColorOutputMode=$('colorOutputMode').value;settings.FloatingCenterAutoCloseSeconds=Math.max(1,Math.min(30,Number($('floatingCenterAutoCloseSeconds').value)||5));$('floatingCenterAutoCloseSeconds').value=settings.FloatingCenterAutoCloseSeconds;settings.UpdateChannel=$('releaseChannel').value;
 const args={theme:settings.Theme,lightTheme:JSON.stringify(settings.LightTheme),darkTheme:JSON.stringify(settings.DarkTheme),colorOutputMode:settings.ColorOutputMode,floatingCenterAutoCloseSeconds:settings.FloatingCenterAutoCloseSeconds,updateChannel:settings.UpdateChannel};Object.entries(toggles).forEach(([id,key])=>args[id]=settings[key]?'1':'0');Object.entries(ranges).forEach(([id,key])=>args[id]=settings[key]);return new URLSearchParams(args).toString();}
function save(){clearTimeout(timer);const data=payload();apply();if(saving){queued=true;return;}if(data===lastSaved)return;saving=true;flight=data;queued=false;$('saveStatus').textContent='正在保存…';$('retrySettings').hidden=true;post('settings',data);}
window.CDBoxSettingsSaved=function(ok){saving=false;if(ok){lastSaved=flight;$('saveStatus').textContent='已自动保存';if(queued){queued=false;save();}}else{$('saveStatus').textContent='保存失败';$('retrySettings').hidden=false;}};
$('retrySettings').onclick=save;
function changed(){p().Preset='custom';$('themePreset').value='custom';save();}
for(const id of ['Accent','Background','Foreground']){$(id).onchange=function(){if(!/^#[a-f0-9]{6}$/i.test(this.value)){this.setAttribute('aria-invalid','true');$('themeHint').textContent='请输入 #RRGGBB 格式的六位颜色值。';return;}p()[id]=this.value.toUpperCase();$(id+'Picker').value=this.value;this.removeAttribute('aria-invalid');$('themeHint').textContent='对比度调整分隔线与控件边界的清晰程度。';changed();};$(id+'Picker').oninput=function(){p()[id]=this.value.toUpperCase();$(id).value=p()[id];apply();};$(id+'Picker').onchange=changed;}
for(const id of ['AccentSource','UiFont','ContentFont','UiWeight','ContentWeight'])$(id).onchange=function(){p()[id]=id.endsWith('Weight')?Number(this.value):this.value;changed();};
$('Contrast').oninput=function(){p().Contrast=Number(this.value);$('contrastValue').textContent=this.value;apply();};$('Contrast').onchange=changed;
$('themePreset').onchange=function(){if(this.value==='custom')return;const preset=presets.find(x=>x.Id===this.value);settings[mode()==='dark'?'DarkTheme':'LightTheme']=clone(mode()==='dark'?preset.Dark:preset.Light);draw();save();};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{settings.Theme=b.dataset.mode;draw();save();});
Object.keys(toggles).concat(Object.keys(ranges),['colorOutputMode','floatingCenterAutoCloseSeconds']).forEach(id=>$(id).addEventListener('change',save));
document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-section]').forEach(x=>x.setAttribute('aria-current',x===b?'page':'false'));document.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==b.dataset.section);$('sectionTitle').textContent=b.textContent;document.querySelector('.settings-content').scrollTop=0;});
document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>post(b.dataset.route,''));
$('copyTheme').onclick=()=>post('copyTheme',JSON.stringify({format:'cdbox-theme-v1',mode:mode(),profile:p()},null,2));
$('importTheme').onclick=()=>{$('themeImportText').value='';$('importError').textContent='';$('themeImportDialog').showModal();$('themeImportText').focus();};
$('applyImport').onclick=()=>{try{const data=JSON.parse($('themeImportText').value),v=data.profile;if(data.format!=='cdbox-theme-v1'||!v||['Accent','Background','Foreground'].some(k=>!/^#[a-f0-9]{6}$/i.test(v[k]))||!Object.keys(fonts).includes(v.UiFont)||v.UiFont==='inherit'||!Object.keys(fonts).includes(v.ContentFont)||!Number.isFinite(v.Contrast)||v.Contrast<0||v.Contrast>100||![400,500,600].includes(v.UiWeight)||![400,500,600].includes(v.ContentWeight)||!['custom','foreground'].includes(v.AccentSource))throw Error();const profile={};for(const key of ['Accent','Background','Foreground','AccentSource','UiFont','ContentFont','UiWeight','ContentWeight','Contrast'])profile[key]=v[key];profile.Preset='custom';settings[mode()==='dark'?'DarkTheme':'LightTheme']=profile;$('themeImportDialog').close();draw();save();}catch(e){$('importError').textContent='主题格式无效，请粘贴“复制主题”生成的完整 JSON。';}};
window.CDBoxStudioToast=function(message,kind){if(kind==='success'&&message==='Studio 设置已保存')return;const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3200);};
window.CDBoxReleaseUpdates.init(function(name,arg){if(name==='settings')save();else post(name,arg);},payload);draw();lastSaved=payload();post('ready','settings');
})();";
    }
}
